      parseFailure: parseFailureCount,
      largeP2P: largeP2PCount
    },
    message: hitlRequired
      ? `${flaggedTransactions.length} transaction(s) flagged for review. Breakdown: ${lowConfidenceCount} low confidence, ${spikeCount} unidentifiable spike(s), ${largeOtherCount} large unclassified credit(s), ${largeP2PCount} large P2P transfer(s), ${parseFailureCount} parse failure(s).`
      : `All ${allTransactions.length} transactions passed confidence and quality checks.`
  },

  // === Flagged Transactions (for review form) ===
  flaggedTransactions: flaggedTransactions,

  // === ALL Transactions (frontend holds these) ===
  allTransactions: allTransactions,

  // === Category Options (for review form dropdowns) ===
  categoryOptions: {
    CREDIT: [...CREDIT_CATEGORIES, ...EITHER_DIRECTION],
    DEBIT: [...DEBIT_CATEGORIES, ...EITHER_DIRECTION]
  },

  // === Pass through metadata ===
  metadata: {
    itemCount: allItems.length,
    documentMonths: allItems.map(item => item.json.documentMonth).filter(Boolean),
    overallMonthlyMeanIncome: Number(overallMonthlyMeanIncome.toFixed(2)),
