// ============================================================
// CLEAN BINARY — Remove non-document files
// ============================================================
// Strips any binary attachment with MIME type application/octet-stream
// Place AFTER base64_to_binary, BEFORE classify_bankStatements
// ============================================================

const output = [];

for (const item of $input.all()) {
  if (!item.binary) {
    output.push(item);
    continue;
  }

  const cleanBinary = {};
  let kept = 0;

  for (const [key, file] of Object.entries(item.binary)) {
    if (file.mimeType === 'application/octet-stream') {
      console.log(`Removed: ${file.fileName || key} (${file.mimeType})`);
      continue;
    }
    cleanBinary[key] = file;
    kept++;
  }

  // Only include the item if it still has at least one valid file
  if (kept > 0) {
    output.push({ json: item.json, binary: cleanBinary });
  }
}

return output;

