// ===================
// STEP 2: HELPER FUNCTIONS
// ===================

/**
 * Compute Coefficient of Variation (CV)
 * CV = (standard deviation / mean) × 100
 * Measures volatility — how much a value swings month to month.
 * Basis: Standard statistical measure. Quantifies what Fannie Mae B3-3.1
 * requires qualitatively: "income must be stable and likely to continue"
 */
function computeCV(values) {
  if (values.length < 2) return 0;
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  if (mean === 0) return 0;
  const variance = values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / values.length;
  const stdDev = Math.sqrt(variance);
  return Number(((stdDev / mean) * 100).toFixed(2));
}

/**
 * Map CV value to stability grade
 */
function getStabilityGrade(cv) {
  for (const tier of STABILITY_THRESHOLDS) {
    if (cv < tier.max) return { grade: tier.grade, label: tier.label, color: tier.color };
  }
  return STABILITY_THRESHOLDS[STABILITY_THRESHOLDS.length - 1];
}

/**
 * Map HHI value to diversification label
 */
function getHHILabel(hhi) {
  for (const tier of HHI_THRESHOLDS) {
    if (hhi <= tier.max) return tier.label;
  }
  return "Concentrated";
}

/**
 * Map DTI to grade — these thresholds ARE industry-prescribed
 */
function getDTIGrade(dti) {
  for (const tier of DTI_THRESHOLDS) {
    if (dti < tier.max) return { grade: tier.grade, label: tier.label };
  }
  return DTI_THRESHOLDS[DTI_THRESHOLDS.length - 1];
}

/**
 * Map composite score to assessment tier
 */
function getAssessment(score) {
  for (const tier of ASSESSMENT_TIERS) {
    if (score >= tier.min) return { label: tier.label, color: tier.color };
  }
  return ASSESSMENT_TIERS[ASSESSMENT_TIERS.length - 1];
}

/**
 * Map balance runway to grade
 */
function getRunwayGrade(months) {
  for (const tier of RUNWAY_THRESHOLDS) {
    if (months >= tier.min) return { grade: tier.grade, label: tier.label };
  }
  return RUNWAY_THRESHOLDS[RUNWAY_THRESHOLDS.length - 1];
}

/**
 * Map balance trend to grade
 */
function getTrendGrade(changePercent) {
  for (const tier of TREND_THRESHOLDS) {
    if (changePercent >= tier.min) return { grade: tier.grade, label: tier.label };
  }
  return TREND_THRESHOLDS[TREND_THRESHOLDS.length - 1];
}


// ===================
// STEP 3: PER-STREAM INCOME ANALYTICS
// ===================
// For each income stream:
//   - Stability (CV + grade)
//   - Recurrence (months present / total months)
//   - Consistency (min, max, band = (max-min)/mean)

const incomeStreams = {};

for (const name of streamNames) {
  const stream = income[name];
  const monthlyValues = Object.values(stream.monthlyIncome);
  const monthlyKeys = Object.keys(stream.monthlyIncome);

  // 3a: Stability (CV)
  const cv = computeCV(monthlyValues);
  const stabilityGrade = getStabilityGrade(cv);

  // 3b: Recurrence
  const monthsPresent = monthlyKeys.length;
  const recurrenceRate = Number((monthsPresent / totalMonths).toFixed(2));

  // 3c: Consistency
  const min = Math.min(...monthlyValues);
  const max = Math.max(...monthlyValues);
  const mean = stream.meanMonthlyIncome;
  const band = mean > 0 ? Number(((max - min) / mean).toFixed(3)) : 0;

  incomeStreams[name] = {
    monthlyIncome: stream.monthlyIncome,
    meanMonthlyIncome: mean,
    projectedAnnualIncome: stream.projectedAnnualIncome,
    stability: {
      cv: cv,
      grade: stabilityGrade.grade,
      label: stabilityGrade.label
    },
    recurrence: {
      monthsPresent: monthsPresent,
      totalMonths: totalMonths,
      rate: recurrenceRate
    },
    consistency: {
      min: min,
      max: max,
      band: band
    }
  };
}


// ===================
// STEP 4: OVERALL INCOME STABILITY
// ===================

const overallMonthlyValues = Object.values(overallData.monthlyIncome);
const overallCV = computeCV(overallMonthlyValues);
const overallStability = getStabilityGrade(overallCV);

const overall = {
  monthlyIncome: overallData.monthlyIncome,
  meanMonthlyIncome: overallData.meanMonthlyIncome,
  projectedAnnualIncome: overallData.projectedAnnualIncome,
  stability: {
    cv: overallCV,
    grade: overallStability.grade,
    label: overallStability.label
  },
  totalMonths: totalMonths,
  streamCount: streamNames.length
};


// ===================
// STEP 5: DIVERSIFICATION (HHI)
// ===================

const totalProjectedAnnual = overallData.projectedAnnualIncome;
const shares = {};
let hhi = 0;

for (const name of streamNames) {
  const share = totalProjectedAnnual > 0
    ? income[name].projectedAnnualIncome / totalProjectedAnnual
    : 0;
  shares[name] = Number(share.toFixed(3));
  hhi += share * share;
}

hhi = Number(hhi.toFixed(3));
const hhiLabel = getHHILabel(hhi);

const diversification = {
  hhi: hhi,
  grade: hhiLabel,
  shares: shares
};


// ===================
// STEP 6: RED FLAG DETECTION
// ===================
// Domain-driven checks that a vibe coder wouldn't think of.
// Each flag gets a type, severity, and plain-English explanation.

const redFlags = [];

for (const name of streamNames) {
  const stream = income[name];
  const monthlyValues = Object.values(stream.monthlyIncome);
  const monthlyEntries = Object.entries(stream.monthlyIncome);
  const mean = stream.meanMonthlyIncome;

  // FLAG 1: Round-number deposits (common in fabricated statements)
  for (const [month, amount] of monthlyEntries) {
    if (amount >= 500 && amount % 100 === 0) {
      redFlags.push({
        type: "ROUND_NUMBER_DEPOSIT",
        severity: "WARNING",
        stream: name,
        month: month,
        amount: amount,
        explanation: `Round-number deposit ($${amount.toLocaleString()}) in ${name.replace(/_/g, ' ').toLowerCase()}. Round deposits are a known indicator of fabricated statements and may warrant verification.`
      });
    }
  }

  // FLAG 2: One-time spike (single deposit > 3× the stream's monthly mean)
  for (const [month, amount] of monthlyEntries) {
    if (mean > 0 && amount > mean * 3) {
      redFlags.push({
        type: "INCOME_SPIKE",
        severity: "WARNING",
        stream: name,
        month: month,
        amount: amount,
        explanation: `Unusually large deposit ($${amount.toLocaleString()}) in ${name.replace(/_/g, ' ').toLowerCase()} — ${(amount / mean).toFixed(1)}× the monthly average. One-time spikes inflate income projections unrealistically.`
      });
    }
  }

  // FLAG 3: Single-appearance stream (only 1 of N months)
  if (monthlyValues.length === 1 && totalMonths > 1) {
    redFlags.push({
      type: "SINGLE_APPEARANCE",
      severity: "INFO",
      stream: name,
      month: monthlyEntries[0][0],
      amount: monthlyEntries[0][1],
      explanation: `${name.replace(/_/g, ' ')} appeared in only 1 of ${totalMonths} months. Cannot establish recurrence — treat as one-time income.`
    });
  }

  // FLAG 4: Missing months (stream present in some but not all months)
  if (monthlyValues.length > 1 && monthlyValues.length < totalMonths) {
    const presentMonths = new Set(Object.keys(stream.monthlyIncome));
    const missingMonths = sortedMonths.filter(m => !presentMonths.has(m));
    redFlags.push({
      type: "MISSING_MONTHS",
      severity: "WARNING",
      stream: name,
      month: missingMonths.join(", "),
      amount: null,
      explanation: `${name.replace(/_/g, ' ')} missing in ${missingMonths.join(", ")}. Income may not be ongoing — verify with borrower.`
    });
  }
}


// ===================
// STEP 7: SUSTAINABLE INCOME
// ===================
// Floor-weighted: use each stream's minimum month instead of mean.
// This is stress-test thinking — what if next month = worst month?
// Basis: Fannie Mae requires declining income to be underwritten
// at the lower amount. We apply this per-stream.

let sustainableMonthly = 0;
for (const name of streamNames) {
  const monthlyValues = Object.values(income[name].monthlyIncome);
  const floorValue = Math.min(...monthlyValues);
  sustainableMonthly += floorValue;
}

const sustainableAnnual = sustainableMonthly * 12;
const projectedAnnual = overallData.projectedAnnualIncome;
const discountFromProjected = projectedAnnual > 0
  ? Number((((projectedAnnual - sustainableAnnual) / projectedAnnual) * 100).toFixed(1))
  : 0;

const sustainableIncome = {
  monthlyFloorWeighted: Number(sustainableMonthly.toFixed(2)),
  annualFloorWeighted: Number(sustainableAnnual.toFixed(2)),
  discountFromProjected: discountFromProjected
};


// ===================
// STEP 8: EXPENSE ANALYSIS
// ===================
// Process the expense data from the aggregation node.

const expSummary = expensesData.summary || {};
const expByType = expensesData.byType || {};
const expCategories = expensesData.categories || {};

// 8a: Expense burn stability — is spending predictable?
const expMonthlyTotals = expensesData.monthlyTotals || {};
const expMonthlyValues = Object.values(expMonthlyTotals);
const burnCV = computeCV(expMonthlyValues);
const burnStability = getStabilityGrade(burnCV);

const totalMonthlyBurn = expSummary.totalMonthlyBurn || 0;

const expenses = {
  categories: expCategories,
  monthlyTotals: expMonthlyTotals,
  byType: expByType,
  summary: {
    totalMonthlyBurn: totalMonthlyBurn,
    fixedMonthly: expSummary.fixedMonthly || 0,
    essentialMonthly: expSummary.essentialMonthly || 0,
    discretionaryMonthly: expSummary.discretionaryMonthly || 0,
    debtMonthly: expSummary.debtMonthly || 0,
    investigateMonthly: expSummary.investigateMonthly || 0,
    fixedExpenseRatio: expSummary.fixedExpenseRatio || 0,
    burnStability: {
      cv: burnCV,
      grade: burnStability.grade,
      label: burnStability.label
    }
  }
};


// ===================
// STEP 8.5: BALANCE BUFFER ANALYSIS
// ===================
// Uses balance fields from transactions to assess:
//   - Financial cushion (average, min, max balance)
//   - Runway (how many months of expenses the min balance covers)
//   - Trend (building reserves vs depleting)
//
// Industry basis: Non-QM lenders require 3-6 months of reserves.
// Angel Oak, Deephaven, A&D Mortgage all document this.
// This is the bank-statement equivalent of reserve verification.

// Collect all balance data points from the checkConfidence node
// which has the full flat transaction list. Fall back to filterTransactions.
let allTxForBalance = [];

try {
  const checkConfData = $('checkConfidence').first().json;
  if (checkConfData && checkConfData.allTransactions) {
    allTxForBalance = checkConfData.allTransactions;
  }
} catch (e) {
  // checkConfidence node not available — pull from filterTransactions
  try {
    const filterItems = $('filterTransactions').all();
    for (const item of filterItems) {
      const d = item.json;
      const arrays = [
        d.incomeTransactions || [],
        d.expenseTransactions || [],
        d.savingsTransactions || [],
        d.investigateTransactions || [],
        d.excludedTransactions || []
      ];
      for (const arr of arrays) {
        allTxForBalance.push(...arr);
      }
    }
  } catch (e2) {
    // No balance data available
  }
}

// Extract valid balance values (non-null, non-zero)
// Zero balances likely indicate parse failures, not actual $0 balance
const balancePoints = [];
for (const tx of allTxForBalance) {
  const bal = tx.balance ?? null;
  if (bal !== null && bal !== undefined && bal > 0) {
    balancePoints.push({
      date: tx.date,
      balance: bal
    });
  }
}

// Sort by date to get chronological order
balancePoints.sort((a, b) => a.date.localeCompare(b.date));

let balanceBuffer;

if (balancePoints.length >= 2) {
  const balanceValues = balancePoints.map(bp => bp.balance);

  const avgBalance = Number(
    (balanceValues.reduce((a, b) => a + b, 0) / balanceValues.length).toFixed(2)
  );
  const minBalance = Number(Math.min(...balanceValues).toFixed(2));
  const maxBalance = Number(Math.max(...balanceValues).toFixed(2));

  // Runway: how many months of expenses can they survive on their minimum balance?
  const runwayMonths = totalMonthlyBurn > 0
    ? Number((minBalance / totalMonthlyBurn).toFixed(1))
    : null;

  const runwayGradeResult = runwayMonths !== null
    ? getRunwayGrade(runwayMonths)
    : { grade: "UNKNOWN", label: "Cannot calculate — no expense data" };

  // Trend: compare first and last balance
  const startBalance = balancePoints[0].balance;
  const endBalance = balancePoints[balancePoints.length - 1].balance;
  const balanceChange = Number((endBalance - startBalance).toFixed(2));
  const balanceChangePercent = startBalance > 0
    ? Number(((balanceChange / startBalance) * 100).toFixed(1))
    : 0;

  const trendGradeResult = getTrendGrade(balanceChangePercent);

  balanceBuffer = {
    averageBalance: avgBalance,
    minBalance: minBalance,
    maxBalance: maxBalance,
    balanceRunway: {
      months: runwayMonths,
      grade: runwayGradeResult.grade,
      label: runwayGradeResult.label
    },
    balanceTrend: {
      startBalance: startBalance,
      endBalance: endBalance,
      change: balanceChange,
      changePercent: balanceChangePercent,
      grade: trendGradeResult.grade,
      label: trendGradeResult.label
    },
    dataPoints: balancePoints.length,
    note: `Based on ${balancePoints.length} transaction balance snapshots across the analysis period.`
  };

  // RED FLAGS — Balance-specific
  // Low balance: minimum balance covers less than 1 month of expenses
  if (runwayMonths !== null && runwayMonths < 1) {
    redFlags.push({
      type: "LOW_BALANCE",
      severity: "WARNING",
      stream: "BALANCE",
      month: balancePoints.find(bp => bp.balance === minBalance)?.date || "unknown",
      amount: minBalance,
      explanation: `Minimum account balance ($${minBalance.toLocaleString()}) covers only ${runwayMonths} months of expenses. Borrower has minimal financial cushion.`
    });
  }

  // Depleting balance: balance dropped 20%+ over the period
  if (balanceChangePercent <= -20) {
    redFlags.push({
      type: "DEPLETING_BALANCE",
      severity: "WARNING",
      stream: "BALANCE",
      month: `${balancePoints[0].date} → ${balancePoints[balancePoints.length - 1].date}`,
      amount: balanceChange,
      explanation: `Account balance decreased ${Math.abs(balanceChangePercent)}% over the analysis period ($${startBalance.toLocaleString()} → $${endBalance.toLocaleString()}). Borrower may be depleting reserves.`
    });
  }

} else {
  // Not enough balance data
  balanceBuffer = {
    averageBalance: null,
    minBalance: null,
    maxBalance: null,
    balanceRunway: {
      months: null,
      grade: "INSUFFICIENT_DATA",
      label: "Not enough balance data points to analyze"
    },
    balanceTrend: {
      startBalance: null,
      endBalance: null,
      change: null,
      changePercent: null,
      grade: "INSUFFICIENT_DATA",
      label: "Not enough balance data points to analyze"
    },
    dataPoints: balancePoints.length,
    note: "Insufficient balance data for buffer analysis."
  };
}


// ===================
// STEP 9: CASH FLOW ANALYSIS
// ===================
// Residual income = income - expenses per month
// This answers: "After paying all bills, is there enough left?"

const monthlyResidual = {};
const meanMonthlyIncome = overallData.meanMonthlyIncome;

for (const month of sortedMonths) {
  const incomeVal = overallData.monthlyIncome[month] || 0;
  const expenseVal = expMonthlyTotals[month] || 0;
  monthlyResidual[month] = Number((incomeVal - expenseVal).toFixed(2));
}

const residualValues = Object.values(monthlyResidual);
const meanResidual = residualValues.length > 0
  ? Number((residualValues.reduce((a, b) => a + b, 0) / residualValues.length).toFixed(2))
  : 0;

const residualCV = computeCV(residualValues.map(v => Math.max(v, 0)));
const residualStability = getStabilityGrade(residualCV);

// Savings rate: what % of income is left after expenses?
const savingsRate = meanMonthlyIncome > 0
  ? Number(((meanResidual / meanMonthlyIncome) * 100).toFixed(1))
  : 0;

const cashFlow = {
  monthlyResidual: monthlyResidual,
  meanResidual: meanResidual,
  residualStability: {
    cv: residualCV,
    grade: residualStability.grade,
    label: residualStability.label
  },
  savingsRate: savingsRate
};


// ===================
// STEP 10: DEBT ANALYSIS (DTI)
// ===================
// DTI = Monthly Debt Payments / Gross Monthly Income × 100
// DTI Thresholds ARE industry-prescribed.

const identifiedDebtPayments = expSummary.debtMonthly || 0;

const estimatedDTI = meanMonthlyIncome > 0
  ? Number(((identifiedDebtPayments / meanMonthlyIncome) * 100).toFixed(1))
  : 0;

// Estimate monthly payment for the new loan
// Using simple annuity formula: PMT = P × [r(1+r)^n] / [(1+r)^n - 1]
// Assumptions: 8% annual rate, 36-month term (personal loan defaults)
const annualRate = 0.08;
const monthlyRate = annualRate / 12;
const loanTermMonths = 36;
const estimatedNewLoanPayment = monthlyRate > 0
  ? Number((loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, loanTermMonths)) /
    (Math.pow(1 + monthlyRate, loanTermMonths) - 1)).toFixed(2))
  : Number((loanAmount / loanTermMonths).toFixed(2));

const dtiWithNewLoan = meanMonthlyIncome > 0
  ? Number((((identifiedDebtPayments + estimatedNewLoanPayment) / meanMonthlyIncome) * 100).toFixed(1))
  : 0;

const dtiGradeResult = getDTIGrade(dtiWithNewLoan);

const debtAnalysis = {
  identifiedDebtPayments: identifiedDebtPayments,
  estimatedDTI: estimatedDTI,
  estimatedNewLoanMonthlyPayment: estimatedNewLoanPayment,
  dtiWithNewLoan: dtiWithNewLoan,
  dtiGrade: dtiGradeResult.grade,
  dtiLabel: dtiGradeResult.label,
  assumptions: {
    annualRate: "8%",
    termMonths: 36,
    note: "Estimated personal loan terms for DTI projection. Actual terms may vary."
  }
};


// ===================
// STEP 11: DATA CONFIDENCE
// ===================

let confidenceLevel, confidenceNote;

if (totalMonths >= 12) {
  confidenceLevel = "High";
  confidenceNote = "Meets Non-QM bank statement program standards (12+ months).";
} else if (totalMonths >= 6) {
  confidenceLevel = "Good";
  confidenceNote = `Based on ${totalMonths} months. 12+ months preferred for full confidence per Non-QM standards.`;
} else if (totalMonths >= 3) {
  confidenceLevel = "Moderate";
  confidenceNote = `Preliminary assessment based on ${totalMonths} months. Non-QM programs require 12–24 months for production underwriting.`;
} else {
  confidenceLevel = "Low";
  confidenceNote = `Only ${totalMonths} month(s) of data. Insufficient for reliable income assessment. Non-QM standards require 12–24 months.`;
}

const dataConfidence = {
  monthsAnalyzed: totalMonths,
  industryStandard: "12–24 months (Non-QM bank statement programs)",
  confidenceLevel: confidenceLevel,
  note: confidenceNote
};


// ===================
// STEP 12: COMPOSITE SCORE
// ===================

// 12a: Loan-to-income sub-score
const loanToIncome = projectedAnnual > 0
  ? Number(((loanAmount / projectedAnnual) * 100).toFixed(1))
  : 100;

let ltiScore;
if (loanToIncome < 15) ltiScore = 100;
else if (loanToIncome < 30) ltiScore = 70;
else if (loanToIncome < 50) ltiScore = 40;
else ltiScore = 10;

// 12b: Stability sub-score (weighted avg CV across streams)
let weightedCV = 0;
let totalWeight = 0;
for (const name of streamNames) {
  const share = shares[name] || 0;
  const cv = incomeStreams[name].stability.cv;
  weightedCV += cv * share;
  totalWeight += share;
}
if (totalWeight > 0) weightedCV = weightedCV / totalWeight;

let stabilityScore;
if (weightedCV < 5) stabilityScore = 100;
else if (weightedCV < 15) stabilityScore = 75;
else if (weightedCV < 30) stabilityScore = 45;
else stabilityScore = 15;

// 12c: Recurrence sub-score
let recurrenceScore = 0;
let recurrenceCount = 0;
for (const name of streamNames) {
  recurrenceScore += incomeStreams[name].recurrence.rate;
  recurrenceCount++;
}
recurrenceScore = recurrenceCount > 0
  ? Math.round((recurrenceScore / recurrenceCount) * 100)
  : 0;

// 12d: Diversification sub-score
let diversificationScore;
if (hhi < 0.25) diversificationScore = 100;
else if (hhi < 0.50) diversificationScore = 60;
else diversificationScore = 25;

// 12e: Red flag penalty
let redFlagScore = 100;
for (const flag of redFlags) {
  if (flag.severity === "CRITICAL") redFlagScore -= 30;
  else if (flag.severity === "WARNING") redFlagScore -= 10;
  else if (flag.severity === "INFO") redFlagScore -= 3;
}
redFlagScore = Math.max(0, redFlagScore);

// 12f: DTI sub-score
let dtiScore;
if (dtiWithNewLoan < 36) dtiScore = 100;
else if (dtiWithNewLoan < 43) dtiScore = 65;
else if (dtiWithNewLoan < 50) dtiScore = 35;
else dtiScore = 10;

// 12g: Residual income sub-score
let residualScore;
if (savingsRate > 40) residualScore = 100;
else if (savingsRate > 25) residualScore = 80;
else if (savingsRate > 10) residualScore = 50;
else if (savingsRate > 0) residualScore = 25;
else residualScore = 5;

// 12h: Compute weighted composite
const compositeScore = Math.round(
  ltiScore * WEIGHTS.loanToIncome +
  stabilityScore * WEIGHTS.stability +
  recurrenceScore * WEIGHTS.recurrence +
  diversificationScore * WEIGHTS.diversification +
  redFlagScore * WEIGHTS.redFlags +
  dtiScore * WEIGHTS.dti +
  residualScore * WEIGHTS.residualIncome
);

const assessmentResult = getAssessment(compositeScore);


// ===================
// STEP 13: UNDERWRITING SUMMARY
// ===================

const loanToSustainableIncome = sustainableAnnual > 0
  ? Number(((loanAmount / sustainableAnnual) * 100).toFixed(1))
  : 100;

const incomeMultiple = projectedAnnual > 0
  ? Number((projectedAnnual / loanAmount).toFixed(2))
  : 0;

const underwriting = {
  loanAmountRequested: loanAmount,
  loanToIncome: loanToIncome,
  loanToSustainableIncome: loanToSustainableIncome,
  incomeMultiple: incomeMultiple,
  compositeScore: compositeScore,
  compositeBreakdown: {
    loanToIncomeScore: ltiScore,
    stabilityScore: stabilityScore,
    recurrenceScore: recurrenceScore,
    diversificationScore: diversificationScore,
    redFlagScore: redFlagScore,
    dtiScore: dtiScore,
    residualIncomeScore: residualScore
  },
  compositeWeights: WEIGHTS,
  assessment: assessmentResult.label,
  assessmentColor: assessmentResult.color
};


// ===================
// STEP 14: NARRATIVE
// ===================

const streamSummaries = streamNames.map(name => {
  const s = incomeStreams[name];
  const label = name.replace(/_/g, ' ').toLowerCase();
  return `${label} (CV: ${s.stability.cv}%, ${s.stability.label}, floor: $${s.consistency.min.toLocaleString()})`;
}).join("; ");

const flagSummary = redFlags.length > 0
  ? ` ${redFlags.length} flag(s) detected: ${redFlags.map(f => f.type.replace(/_/g, ' ').toLowerCase()).join(", ")}.`
  : " No red flags detected.";

const expenseSummary = expenses.summary.totalMonthlyBurn > 0
  ? ` Monthly expenses: $${expenses.summary.totalMonthlyBurn.toLocaleString()} (${(expenses.summary.fixedExpenseRatio * 100).toFixed(0)}% fixed). Residual income: $${meanResidual.toLocaleString()}/month (${savingsRate}% savings rate).`
  : "";

const dtiSummary = identifiedDebtPayments > 0
  ? ` Existing debt payments: $${identifiedDebtPayments.toLocaleString()}/month. DTI with new loan: ${dtiWithNewLoan}% — ${dtiGradeResult.grade.toLowerCase()}.`
  : ` No existing debt payments identified. DTI with new loan: ${dtiWithNewLoan}% — ${dtiGradeResult.grade.toLowerCase()}.`;

// Balance narrative
let balanceNarrative = "";
if (balanceBuffer && balanceBuffer.averageBalance !== null) {
  const rb = balanceBuffer.balanceRunway;
  const bt = balanceBuffer.balanceTrend;
  balanceNarrative = ` Account balance: avg $${balanceBuffer.averageBalance.toLocaleString()}, min $${balanceBuffer.minBalance.toLocaleString()}. Balance runway: ${rb.months} months — ${rb.grade.toLowerCase()}. Balance trend: ${bt.label.toLowerCase()} (${bt.changePercent > 0 ? '+' : ''}${bt.changePercent}%).`;
}

const narrative = `Borrower shows $${Math.round(projectedAnnual / 1000)}K projected annual income across ${streamNames.length} stream(s) with ${hhiLabel.toLowerCase()} diversification (HHI: ${hhi}). Per-stream analysis: ${streamSummaries}. Overall income stability: ${overallStability.label} (CV: ${overallCV}%).${flagSummary}${expenseSummary}${dtiSummary}${balanceNarrative} Sustainable income (floor-weighted): $${Math.round(sustainableAnnual / 1000)}K (${discountFromProjected}% discount from projected). Loan-to-sustainable-income: ${loanToSustainableIncome}%. Data confidence: ${confidenceLevel} (${totalMonths} months analyzed; industry standard: 12–24). Composite score: ${compositeScore}/100. Assessment: ${assessmentResult.label}.`;


// ===================
// STEP 15: RETURN FINAL OUTPUT
// ===================

return [
  {
    json: {
      incomeStreams: incomeStreams,
      overall: overall,
      diversification: diversification,
      redFlags: redFlags,
      sustainableIncome: sustainableIncome,
      expenses: expenses,
      balanceBuffer: balanceBuffer,
      cashFlow: cashFlow,
      debtAnalysis: debtAnalysis,
      savings: {
        monthlyInvestment: savingsData.monthlyInvestment || {},
        meanMonthly: savingsData.meanMonthly || 0
      },
      underwriting: underwriting,
      dataConfidence: dataConfidence,
      narrative: narrative
    }
  }
];

// ============================================================
// V2 AGGREGATION — Income + Expenses by Category × Month
// ============================================================
// Replaces V1 "Code in JavaScript2" (income-only aggregation).
//
// V1: Aggregated income by category × month, computed mean + projected annual.
// V2: Does the same for income AND adds full expense aggregation:
//     - Expenses by category × month
//     - Expense type breakdown (FIXED / ESSENTIAL / DISCRETIONARY / DEBT)
//     - Monthly totals for each type
//     - Savings tracking (INVESTMENT — positive signal)
//     - Investigate tracking (CASH_WITHDRAWAL, ATM — unclassifiable)
//
// INPUT:  Output from checkConfidence node — contains allTransactions
//         (flat array with _sourceArray field on each transaction)
//         OR output from filterTransactions node (multiple items with
//         incomeTransactions, expenseTransactions arrays)
//
// OUTPUT: Full aggregation for both sides, ready for V2 analytics engine
// ============================================================


// ===================
// HELPER: Safe rounding to avoid floating point noise
// ===================
// JavaScript floating point: 146.82 + 63.14 = 209.95999999999998
// This helper ensures all monetary values stay clean.
function r(value) {
  return Number(value.toFixed(2));
}


// ===================
// STEP 0: COLLECT ALL TRANSACTIONS — HANDLE BOTH INPUT FORMATS
// ===================
// This node can receive input from two sources:
//   A) checkConfidence node → single item with allTransactions flat array
//   B) filterTransactions node → multiple items with typed arrays
//
// We detect the format and extract accordingly.

const allIncome = [];
const allExpenses = [];
const allSavings = [];
const allInvestigate = [];

const items = $input.all();
const firstItem = items[0]?.json;

if (firstItem && firstItem.allTransactions) {
  // -------------------------------------------------------
  // FORMAT A: checkConfidence output (flat allTransactions array)
  // Each transaction has _sourceArray telling us where it belongs.
  // Skip ignored transactions (human marked them for exclusion).
  // -------------------------------------------------------
  for (const tx of firstItem.allTransactions) {
    // Skip transactions that human marked as ignored during HITL review
    if (tx.ignored) continue;

    switch (tx._sourceArray) {
      case "incomeTransactions":
        allIncome.push(tx);
        break;
      case "expenseTransactions":
        allExpenses.push(tx);
        break;
      case "savingsTransactions":
        allSavings.push(tx);
        break;
      case "investigateTransactions":
        allInvestigate.push(tx);
        break;
      // excludedTransactions — intentionally not collected
    }
  }
} else {
  // -------------------------------------------------------
  // FORMAT B: filterTransactions output (multiple items with arrays)
  // This is the V1-compatible format, kept as fallback.
  // -------------------------------------------------------
  for (const item of items) {
    const data = item.json;

    if (data.incomeTransactions) {
      allIncome.push(...data.incomeTransactions);
    }
    if (data.expenseTransactions) {
      allExpenses.push(...data.expenseTransactions);
    }
    if (data.savingsTransactions) {
      allSavings.push(...data.savingsTransactions);
    }
    if (data.investigateTransactions) {
      allInvestigate.push(...data.investigateTransactions);
    }
  }
}


// ===================
// STEP 1: AGGREGATE INCOME (same logic as V1)
// ===================
// Group by category → month → sum amounts
// Then compute mean monthly and projected annual per category

const incomeByCategory = {};
const overallMonthlyIncome = {};

for (const tx of allIncome) {
  const category = tx.transactionCategory;
  const month = tx.date.slice(0, 7); // YYYY-MM
  const amount = Math.abs(tx.amount);

  // Per-category aggregation
  if (!incomeByCategory[category]) {
    incomeByCategory[category] = { monthlyIncome: {} };
  }
  incomeByCategory[category].monthlyIncome[month] =
    r((incomeByCategory[category].monthlyIncome[month] || 0) + amount);

  // Overall monthly total
  overallMonthlyIncome[month] =
    r((overallMonthlyIncome[month] || 0) + amount);
}

// Compute mean and projected annual for each income category
const incomeCategories = Object.keys(incomeByCategory);

for (const category of incomeCategories) {
  const months = Object.keys(incomeByCategory[category].monthlyIncome);
  const values = Object.values(incomeByCategory[category].monthlyIncome);

  if (months.length === 0) {
    delete incomeByCategory[category];
    continue;
  }

  const total = values.reduce((a, b) => a + b, 0);
  const mean = total / months.length;

  incomeByCategory[category].meanMonthlyIncome = r(mean);
  incomeByCategory[category].projectedAnnualIncome = r(mean * 12);
}

// Overall income statistics
const overallIncomeValues = Object.values(overallMonthlyIncome);
const overallIncomeTotal = overallIncomeValues.reduce((a, b) => a + b, 0);
const overallIncomeMean = overallIncomeValues.length > 0
  ? overallIncomeTotal / overallIncomeValues.length
  : 0;

const OVERALL_INCOME = {
  monthlyIncome: overallMonthlyIncome,
  meanMonthlyIncome: r(overallIncomeMean),
  projectedAnnualIncome: r(overallIncomeMean * 12)
};


// ===================
// STEP 2: AGGREGATE EXPENSES (NEW in V2)
// ===================
// Same pattern as income: group by category → month → sum amounts
// PLUS: track expense type (FIXED/ESSENTIAL/DISCRETIONARY/DEBT)

const expenseByCategory = {};
const overallMonthlyExpense = {};

// Monthly totals by expense type
const monthlyByType = {
  FIXED: {},
  ESSENTIAL: {},
  DISCRETIONARY: {},
  DEBT: {},
  INVESTIGATE: {}
};

for (const tx of allExpenses) {
  const category = tx.transactionCategory;
  const month = tx.date.slice(0, 7); // YYYY-MM
  const amount = Math.abs(tx.amount);
  const expenseType = tx.expenseType; // Set by filterTransactions node

  // Per-category aggregation
  if (!expenseByCategory[category]) {
    expenseByCategory[category] = {
      monthlyExpense: {},
      expenseType: expenseType
    };
  }
  expenseByCategory[category].monthlyExpense[month] =
    r((expenseByCategory[category].monthlyExpense[month] || 0) + amount);

  // Overall monthly total
  overallMonthlyExpense[month] =
    r((overallMonthlyExpense[month] || 0) + amount);

  // Monthly by type
  if (monthlyByType[expenseType]) {
    monthlyByType[expenseType][month] =
      r((monthlyByType[expenseType][month] || 0) + amount);
  }
}

// Compute mean monthly for each expense category
const expenseCategories = Object.keys(expenseByCategory);

for (const category of expenseCategories) {
  const months = Object.keys(expenseByCategory[category].monthlyExpense);
  const values = Object.values(expenseByCategory[category].monthlyExpense);

  if (months.length === 0) {
    delete expenseByCategory[category];
    continue;
  }

  const total = values.reduce((a, b) => a + b, 0);
  const mean = total / months.length;

  expenseByCategory[category].meanMonthly = r(mean);
}

// Overall expense statistics
const overallExpenseValues = Object.values(overallMonthlyExpense);
const overallExpenseTotal = overallExpenseValues.reduce((a, b) => a + b, 0);
const overallExpenseMean = overallExpenseValues.length > 0
  ? overallExpenseTotal / overallExpenseValues.length
  : 0;


// ===================
// STEP 3: EXPENSE TYPE SUMMARIES
// ===================
// Compute mean monthly for each expense type (FIXED, ESSENTIAL, etc.)

function meanOfObject(obj) {
  const values = Object.values(obj);
  if (values.length === 0) return 0;
  return r(values.reduce((a, b) => a + b, 0) / values.length);
}

const fixedMonthly = meanOfObject(monthlyByType.FIXED);
const essentialMonthly = meanOfObject(monthlyByType.ESSENTIAL);
const discretionaryMonthly = meanOfObject(monthlyByType.DISCRETIONARY);
const debtMonthly = meanOfObject(monthlyByType.DEBT);
const investigateMonthly = meanOfObject(monthlyByType.INVESTIGATE);

const totalMonthlyBurn = r(overallExpenseMean);

// Fixed expense ratio: what share of total spending is non-negotiable?
// Fixed = FIXED + DEBT (both are obligations the borrower can't easily reduce)
const fixedPlusDebt = r(fixedMonthly + debtMonthly);
const fixedExpenseRatio = totalMonthlyBurn > 0
  ? Number((fixedPlusDebt / totalMonthlyBurn).toFixed(3))
  : 0;


// ===================
// STEP 4: SAVINGS TRACKING (INVESTMENT)
// ===================
// Savings are NOT expenses — they're a positive signal.
// Track them separately.

const savingsByMonth = {};

for (const tx of allSavings) {
  const month = tx.date.slice(0, 7);
  const amount = Math.abs(tx.amount);
  savingsByMonth[month] = r((savingsByMonth[month] || 0) + amount);
}

const savingsMean = meanOfObject(savingsByMonth);


// ===================
// STEP 5: BUILD OUTPUT
// ===================

// Income side (same structure as V1, so V2 analytics engine can read it)
const incomeOutput = {};
for (const category of Object.keys(incomeByCategory)) {
  incomeOutput[category] = incomeByCategory[category];
}
incomeOutput["OVERALL"] = OVERALL_INCOME;

return [
  {
    json: {
      // === INCOME (V1-compatible structure) ===
      ...incomeOutput,

      // === EXPENSES (NEW in V2) ===
      expenses: {
        categories: expenseByCategory,
        monthlyTotals: overallMonthlyExpense,
        byType: {
          FIXED: monthlyByType.FIXED,
          ESSENTIAL: monthlyByType.ESSENTIAL,
          DISCRETIONARY: monthlyByType.DISCRETIONARY,
          DEBT: monthlyByType.DEBT,
          INVESTIGATE: monthlyByType.INVESTIGATE
        },
        summary: {
          totalMonthlyBurn: totalMonthlyBurn,
          fixedMonthly: fixedMonthly,
          essentialMonthly: essentialMonthly,
          discretionaryMonthly: discretionaryMonthly,
          debtMonthly: debtMonthly,
          investigateMonthly: investigateMonthly,
          fixedExpenseRatio: fixedExpenseRatio
        }
      },

      // === SAVINGS (NEW in V2) ===
      savings: {
        monthlyInvestment: savingsByMonth,
        meanMonthly: savingsMean
      }
    }
  }
];

const d = $json;
const streams = Object.keys(d.incomeStreams || {}).length;
const assessment = d.underwriting?.assessment || "REVIEW";
const months = d.dataConfidence?.monthsAnalyzed || 0;
const flags = (d.redFlags || []).length;

const strength = d.cashFlow?.savingsRate > 50 
  ? "Strong savings rate with stable recurring income"
  : "Multi-stream income with diversified sources";

const concern = months < 6 
  ? `only ${months} months of data (12-24 recommended)`
  : flags > 2 
  ? `${flags} red flags requiring manual verification`
  : "limited data history";

return [{
  json: {
    ...d,
    shortNarrative: `${strength}, but ${concern}.`
  }
}];
